"use client"

// From chatcn, chat, voice and agent UI for shadcn: https://chatcn.dev

import * as React from "react"
import { cn } from "@/lib/utils"

/** chatcn theme variables and utilities this file uses, light and dark. */
const CHATCN_CSS = ":root{--chatcn-bg:oklch(1 0 0);--chatcn-border:var(--chatcn-gray-400);--chatcn-card:oklch(1 0 0);--chatcn-fg:var(--chatcn-gray-1000);--chatcn-fg-faint:var(--chatcn-gray-700);--chatcn-fg-muted:var(--chatcn-gray-900);--chatcn-fg-subtle:var(--chatcn-gray-800);--chatcn-fill-active:var(--chatcn-gray-300);--chatcn-gray-1000:oklch(0.145 0 0);--chatcn-gray-300:oklch(0.930 0 0);--chatcn-gray-400:oklch(0.910 0 0);--chatcn-gray-700:oklch(0.700 0 0);--chatcn-gray-800:oklch(0.525 0 0);--chatcn-gray-900:oklch(0.440 0 0);--chatcn-radius-lg:12px;--chatcn-shadow-sm:0 0 0 1px oklch(0 0 0 / 0.06), 0 1px 2px -1px oklch(0 0 0 / 0.06), 0 2px 4px oklch(0 0 0 / 0.04)}.dark{--chatcn-bg:oklch(0.145 0 0);--chatcn-border:var(--chatcn-gray-400);--chatcn-card:oklch(0.175 0 0);--chatcn-fg:var(--chatcn-gray-1000);--chatcn-fg-faint:var(--chatcn-gray-700);--chatcn-fg-muted:var(--chatcn-gray-900);--chatcn-fg-subtle:var(--chatcn-gray-800);--chatcn-fill-active:var(--chatcn-gray-300);--chatcn-gray-1000:oklch(0.970 0 0);--chatcn-gray-300:oklch(0.255 0 0);--chatcn-gray-400:oklch(0.285 0 0);--chatcn-gray-700:oklch(0.500 0 0);--chatcn-gray-800:oklch(0.620 0 0);--chatcn-gray-900:oklch(0.720 0 0);--chatcn-shadow-sm:0 0 0 1px oklch(1 0 0 / 0.08), inset 0 1px 0 oklch(1 0 0 / 0.03), 0 2px 4px oklch(0 0 0 / 0.4)}"
if (typeof document !== "undefined" && !document.getElementById("chatcn-waveform")) {
  const style = document.createElement("style")
  style.id = "chatcn-waveform"
  style.textContent = CHATCN_CSS
  document.head.appendChild(style)
}

/* -------------------------------------------------------------------------------------------------
 * Level and band sources
 *
 * Voice components take audio levels as plain values or as getters. A number re-renders the
 * component on every change, which is fine at 20 updates a second. A getter is read once per
 * animation frame and never re-renders anything, which is what a 60 fps meter wants.
 * -----------------------------------------------------------------------------------------------*/

/** A level from 0 to 1, or a function that returns the current one. */
type ChatcnLevel = number | (() => number)

/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export interface WaveformProps extends Omit<React.ComponentProps<"div">, "children"> {
  /** `bars` for rounded level bars, `line` for one continuous stroke. Default `bars`. */
  variant?: "bars" | "line"
  /**
   * Live level from 0 to 1. The waveform keeps a scrolling history, newest at the end. Pass a
   * getter (`() => number`) to scroll at 60 fps without re-rendering.
   */
  level?: ChatcnLevel
  /** False rests on a flat baseline and stops the scroll. Default true. */
  active?: boolean
  /** A recorded waveform (any length, any scale) to show instead of live levels. */
  peaks?: number[]
  /** Played portion of `peaks`, from 0 to 1. Played bars are ink, the rest faint. */
  progress?: number
  /** Bar width in px, or the stroke width for `line`. Default 3 for bars, 1.5 for line. */
  barWidth?: number
  /** Gap between bars in px. Default 2. */
  gap?: number
  /** Force reduced motion on or off. Defaults to the user's setting. */
  reducedMotion?: boolean
  /** Accessible name. Defaults to "Input level", or "Waveform, 40 percent played" for peaks. */
  label?: string
}

/* -------------------------------------------------------------------------------------------------
 * Reduced motion
 * -----------------------------------------------------------------------------------------------*/

const REDUCED = "(prefers-reduced-motion: reduce)"

/** True when the user asked for reduced motion. Updates live when the setting changes. */
function useChatcnPrefersReducedMotion() {
  const [reduced, setReduced] = React.useState(false)
  React.useEffect(() => {
    const query = window.matchMedia?.(REDUCED)
    if (!query) return
    const update = () => setReduced(query.matches)
    update()
    query.addEventListener("change", update)
    return () => query.removeEventListener("change", update)
  }, [])
  return reduced
}

/* -------------------------------------------------------------------------------------------------
 * Theme colors for canvas
 * -----------------------------------------------------------------------------------------------*/

/** Resolved theme colors as CSS strings the canvas understands. Alpha goes through `globalAlpha`. */
interface ChatcnVoiceColors {
  /** The canvas `color`, so `text-*` classes tint the drawing. Defaults to the foreground. */
  fg: string
  muted: string
  subtle: string
  faint: string
  border: string
  fill: string
  bg: string
}

/* -------------------------------------------------------------------------------------------------
 * useChatcnVoiceCanvas
 * -----------------------------------------------------------------------------------------------*/

interface ChatcnVoiceFrame {
  ctx: CanvasRenderingContext2D
  /** CSS pixels. The context is already scaled for the device pixel ratio. */
  width: number
  height: number
  dpr: number
  /** Seconds of animated time. Only advances while frames run, so nothing jumps on resume. */
  t: number
  /** Seconds since the previous frame, capped at 50 ms. */
  dt: number
  colors: ChatcnVoiceColors
  reducedMotion: boolean
}

/** Draws one frame. Return true to keep animating, false to sleep until `invalidate()`. */
type ChatcnVoiceDraw = (frame: ChatcnVoiceFrame) => boolean

interface UseChatcnVoiceCanvasOptions {
  /** Force reduced motion on or off. Defaults to the user's setting. */
  reducedMotion?: boolean
}

interface ChatcnVoiceCanvas {
  /** Attach to a `<canvas>`. Its CSS size is observed; the backing store follows it. */
  ref: (element: HTMLCanvasElement | null) => void
  /** Ask for a frame. Call after props change; the loop sleeps when the drawing settles. */
  invalidate: () => void
  reducedMotion: boolean
  /** False until the canvas has a 2D context. Render a fallback while false. */
  supported: boolean
}

function readColors(element: Element): ChatcnVoiceColors {
  const style = getComputedStyle(element)
  const v = (name: string, fallback: string) => style.getPropertyValue(name).trim() || fallback
  const fg = style.color || v("--chatcn-fg", "currentColor")
  return {
    fg,
    muted: v("--chatcn-fg-muted", fg),
    subtle: v("--chatcn-fg-subtle", fg),
    faint: v("--chatcn-fg-faint", fg),
    border: v("--chatcn-border", fg),
    fill: v("--chatcn-fill-active", fg),
    bg: v("--chatcn-bg", "transparent"),
  }
}

/**
 * A sleeping requestAnimationFrame loop for voice visuals. Handles device pixel ratio, resizes,
 * theme changes (colors are re-read from CSS, so dark mode and `text-*` classes just work), and
 * pauses while the canvas is off screen or the tab is hidden. The draw function decides when to
 * sleep, so a settled orb or a silent meter costs nothing.
 */
function useChatcnVoiceCanvas(
  draw: ChatcnVoiceDraw,
  options: UseChatcnVoiceCanvasOptions = {},
): ChatcnVoiceCanvas {
  const prefersReduced = useChatcnPrefersReducedMotion()
  const reducedMotion = options.reducedMotion ?? prefersReduced
  const [supported, setSupported] = React.useState(true)

  const drawRef = React.useRef(draw)
  drawRef.current = draw
  const reducedRef = React.useRef(reducedMotion)
  reducedRef.current = reducedMotion

  const s = React.useRef({
    canvas: null as HTMLCanvasElement | null,
    ctx: null as CanvasRenderingContext2D | null,
    colors: null as ChatcnVoiceColors | null,
    raf: 0,
    running: false,
    visible: true,
    last: 0,
    t: 0,
    cleanup: [] as (() => void)[],
  })

  const frame = React.useCallback((now: number) => {
    const st = s.current
    st.raf = 0
    const canvas = st.canvas
    const ctx = st.ctx
    if (!canvas || !ctx) {
      st.running = false
      return
    }
    const dt = st.last ? Math.min(0.05, Math.max(0, (now - st.last) / 1000)) : 1 / 60
    st.last = now
    st.t += dt

    const dpr = Math.min(3, window.devicePixelRatio || 1)
    const width = canvas.clientWidth
    const height = canvas.clientHeight
    const bw = Math.max(1, Math.round(width * dpr))
    const bh = Math.max(1, Math.round(height * dpr))
    if (canvas.width !== bw || canvas.height !== bh) {
      canvas.width = bw
      canvas.height = bh
    }
    if (!st.colors) st.colors = readColors(canvas)
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
    ctx.clearRect(0, 0, width, height)
    ctx.globalAlpha = 1

    const keep =
      width > 0 &&
      height > 0 &&
      drawRef.current({
        ctx,
        width,
        height,
        dpr,
        t: st.t,
        dt,
        colors: st.colors,
        reducedMotion: reducedRef.current,
      })

    if (keep && st.visible) {
      st.raf = requestAnimationFrame(frameRef.current)
    } else {
      st.running = false
      st.last = 0
    }
  }, [])
  const frameRef = React.useRef(frame)
  frameRef.current = frame

  const invalidate = React.useCallback(() => {
    const st = s.current
    if (st.running || !st.ctx) return
    st.running = true
    st.raf = requestAnimationFrame(frameRef.current)
  }, [])

  const ref = React.useCallback(
    (canvas: HTMLCanvasElement | null) => {
      const st = s.current
      for (const fn of st.cleanup) fn()
      st.cleanup = []
      if (st.raf) cancelAnimationFrame(st.raf)
      st.raf = 0
      st.running = false
      st.canvas = canvas
      st.ctx = null
      st.colors = null
      if (!canvas) return

      const ctx = canvas.getContext("2d")
      if (!ctx) {
        setSupported(false)
        return
      }
      st.ctx = ctx

      const refreshColors = () => {
        st.colors = null
        invalidate()
      }

      const resize = new ResizeObserver(() => invalidate())
      resize.observe(canvas)
      st.cleanup.push(() => resize.disconnect())

      const io = new IntersectionObserver((entries) => {
        const entry = entries[entries.length - 1]
        st.visible = entry ? entry.isIntersecting && !document.hidden : true
        if (st.visible) invalidate()
      })
      io.observe(canvas)
      st.cleanup.push(() => io.disconnect())

      const onVisibility = () => {
        st.visible = !document.hidden
        if (st.visible) invalidate()
      }
      document.addEventListener("visibilitychange", onVisibility)
      st.cleanup.push(() => document.removeEventListener("visibilitychange", onVisibility))

      // Theme switches toggle a class or attribute on <html>; the system theme fires a query.
      const mo = new MutationObserver(refreshColors)
      mo.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ["class", "style", "data-theme"],
      })
      st.cleanup.push(() => mo.disconnect())
      const dark = window.matchMedia?.("(prefers-color-scheme: dark)")
      dark?.addEventListener("change", refreshColors)
      st.cleanup.push(() => dark?.removeEventListener("change", refreshColors))

      invalidate()
    },
    [invalidate],
  )

  // Reduced motion changes the drawing, so draw again.
  React.useEffect(() => {
    void reducedMotion
    invalidate()
  }, [reducedMotion, invalidate])

  React.useEffect(
    () => () => {
      const st = s.current
      for (const fn of st.cleanup) fn()
      if (st.raf) cancelAnimationFrame(st.raf)
    },
    [],
  )

  return { ref, invalidate, reducedMotion, supported }
}

/** Resamples peaks to `count` values by taking the loudest in each slice, normalized to 1. */
function resamplePeaks(peaks: number[], count: number): number[] {
  if (count <= 0 || peaks.length === 0) return []
  let max = 0
  for (const p of peaks) max = Math.max(max, Math.abs(p))
  const scale = max > 0 ? 1 / max : 0
  const out = new Array<number>(count)
  for (let i = 0; i < count; i++) {
    const from = Math.floor((i * peaks.length) / count)
    const to = Math.max(from + 1, Math.floor(((i + 1) * peaks.length) / count))
    let m = 0
    for (let j = from; j < to; j++) m = Math.max(m, Math.abs(peaks[j] ?? 0))
    out[i] = m * scale
  }
  return out
}

const clamp = (v: number) => Math.min(1, Math.max(0, v))

/** Speech sits low on a linear scale; a gentle curve lets quiet syllables still read. */
const shape = (v: number) => clamp(v) ** 0.75

/** One stroke whose swing follows the levels: alternate samples go up and down, smoothed. */
function drawLine(
  ctx: CanvasRenderingContext2D,
  values: number[],
  x0: number,
  step: number,
  height: number,
  lineWidth: number,
) {
  const mid = height / 2
  const amp = (height - lineWidth * 2) / 2
  const pts: [number, number][] = values.map((v, i) => [
    x0 + i * step + step / 2,
    mid + (i % 2 === 0 ? -1 : 1) * shape(v) * amp,
  ])
  if (pts.length < 2) return
  ctx.beginPath()
  const first = pts[0] as [number, number]
  ctx.moveTo(first[0], first[1])
  for (let i = 1; i < pts.length - 1; i++) {
    const p = pts[i] as [number, number]
    const q = pts[i + 1] as [number, number]
    ctx.quadraticCurveTo(p[0], p[1], (p[0] + q[0]) / 2, (p[1] + q[1]) / 2)
  }
  const last = pts[pts.length - 1] as [number, number]
  ctx.lineTo(last[0], last[1])
  ctx.lineWidth = lineWidth
  ctx.lineJoin = "round"
  ctx.lineCap = "round"
  ctx.stroke()
}

/* -------------------------------------------------------------------------------------------------
 * Drawing
 * -----------------------------------------------------------------------------------------------*/

function drawBars(
  ctx: CanvasRenderingContext2D,
  values: number[],
  x0: number,
  step: number,
  bar: number,
  height: number,
) {
  const mid = height / 2
  const min = Math.min(bar, height)
  ctx.beginPath()
  for (let i = 0; i < values.length; i++) {
    const h = Math.max(min, shape(values[i] ?? 0) * height)
    const x = x0 + i * step
    if (typeof ctx.roundRect === "function") ctx.roundRect(x, mid - h / 2, bar, h, bar / 2)
    else ctx.rect(x, mid - h / 2, bar, h)
  }
  ctx.fill()
}

const clamp01 = (value: number) => (Number.isFinite(value) ? Math.min(1, Math.max(0, value)) : 0)

/** Reads a level source. Undefined reads as silence. */
function readLevel(level: ChatcnLevel | undefined): number {
  if (level === undefined) return 0
  return clamp01(typeof level === "function" ? level() : level)
}

/** New samples per second. With 3 px bars and 2 px gaps the history scrolls at 80 px a second. */
const RATE = 16

/** Width of the fade at the oldest end, as a fraction of the width. */
const FADE = 0.14

/** Fades the oldest end out, so history leaves instead of being cut off. Alpha only. */
function fadeEdge(ctx: CanvasRenderingContext2D, width: number, height: number, rtl: boolean) {
  const w = width * FADE
  const g = rtl
    ? ctx.createLinearGradient(width, 0, width - w, 0)
    : ctx.createLinearGradient(0, 0, w, 0)
  g.addColorStop(0, "black")
  g.addColorStop(1, "transparent")
  ctx.save()
  ctx.globalCompositeOperation = "destination-out"
  ctx.globalAlpha = 1
  ctx.fillStyle = g
  ctx.fillRect(rtl ? width - w : 0, 0, w, height)
  ctx.restore()
}

/* -------------------------------------------------------------------------------------------------
 * Waveform
 * -----------------------------------------------------------------------------------------------*/

/**
 * Live input or output levels as a scrolling history, the voice-memo way: each bar is a moment,
 * newest at the end, the oldest fading out at the start. Or a recorded waveform with a played
 * portion. Canvas, sized by CSS; colors follow the theme and `text-*` classes.
 */
export function Waveform({
  variant = "bars",
  level,
  active = true,
  peaks,
  progress,
  barWidth,
  gap = 2,
  reducedMotion: reducedProp,
  label,
  className,
  ...props
}: WaveformProps) {
  const prefersReduced = useChatcnPrefersReducedMotion()
  const reducedMotion = reducedProp ?? prefersReduced
  const bar = barWidth ?? (variant === "line" ? 1.5 : 3)
  // The line swings once per sample, so it samples sparser than bars to read as a wave.
  const step = variant === "line" ? Math.max(10, bar + gap) : bar + gap
  const isStatic = peaks !== undefined

  const props$ = React.useRef({ variant, level, active, peaks, progress, bar, gap, step, isStatic })
  props$.current = { variant, level, active, peaks, progress, bar, gap, step, isStatic }

  const m = React.useRef({
    history: [] as number[],
    /** Seconds since the last sample, for the sub-sample scroll offset. */
    since: 0,
    /** Loudest reading since the last sample: bars show peaks, not whatever frame landed. */
    hold: 0,
    rtl: false,
    lastReduced: 0,
  })

  const canvas = useChatcnVoiceCanvas(
    ({ ctx, width, height, dt, t, colors, reducedMotion: reduced }) => {
      const p = props$.current
      const st = m.current
      const count = Math.max(1, Math.floor((width + p.gap) / p.step))
      ctx.fillStyle = colors.fg
      ctx.strokeStyle = colors.fg

      // Recorded: played portion in ink over the faint rest, split mid-bar where progress lands.
      if (p.isStatic) {
        const raw = resamplePeaks(p.peaks ?? [], count)
        const values = st.rtl ? raw.reverse() : raw
        const x0 = (width - (count * p.step - p.gap)) / 2
        const paint = (color: string) => {
          ctx.fillStyle = color
          ctx.strokeStyle = color
          if (p.variant === "line") drawLine(ctx, values, x0, p.step, height, p.bar)
          else drawBars(ctx, values, x0, p.step, p.bar, height)
        }
        paint(colors.faint)
        const split = clamp(p.progress ?? 0) * width
        if (split > 0) {
          ctx.save()
          ctx.beginPath()
          ctx.rect(st.rtl ? width - split : 0, 0, split, height)
          ctx.clip()
          paint(colors.fg)
          ctx.restore()
        }
        return false
      }

      // Resting: a flat run of dots in faint ink, and the history starts over.
      if (!p.active) {
        st.history = []
        st.hold = 0
        ctx.fillStyle = colors.faint
        ctx.strokeStyle = colors.faint
        const values = new Array<number>(count).fill(0)
        if (p.variant === "line") drawLine(ctx, values, 0, p.step, height, p.bar)
        else drawBars(ctx, values, 0, p.step, p.bar, height)
        return false
      }

      const now = readLevel(p.level)

      // Reduced motion: nothing travels. Bars hold their places and show the current level as a
      // centred hump, updated about eight times a second without easing.
      if (reduced) {
        if (t - st.lastReduced >= 0.12 || st.history.length !== count) {
          st.lastReduced = t
          st.history = Array.from({ length: count }, (_, i) => {
            const x = count === 1 ? 0 : (i / (count - 1)) * 2 - 1
            return now * (0.35 + 0.65 * Math.cos((x * Math.PI) / 2) ** 2)
          })
        }
        if (p.variant === "line") drawLine(ctx, st.history, 0, p.step, height, p.bar)
        else drawBars(ctx, st.history, 0, p.step, p.bar, height)
        return true
      }

      st.hold = Math.max(st.hold, now)
      st.since += dt
      const interval = 1 / RATE
      while (st.since >= interval) {
        st.since -= interval
        // The line swings per sample; uneven swings read as a voice, even swings as a tone.
        st.history.push(p.variant === "line" ? st.hold * (0.45 + 0.55 * Math.random()) : st.hold)
        st.hold = now
      }
      // One extra sample slides in from the end as the history scrolls.
      const keep = count + 1
      if (st.history.length > keep) st.history.splice(0, st.history.length - keep)
      const values =
        st.history.length < keep
          ? [...new Array<number>(keep - st.history.length).fill(0), ...st.history]
          : st.history
      const offset = (st.since / interval) * p.step
      // The newest bar lands flush at the end and the history slides toward the start.
      let x0 = width - p.bar - (keep - 1) * p.step - offset
      let drawn = values
      if (st.rtl) {
        drawn = [...values].reverse()
        x0 = offset
      }
      if (p.variant === "line") drawLine(ctx, drawn, x0, p.step, height, p.bar)
      else drawBars(ctx, drawn, x0, p.step, p.bar, height)
      fadeEdge(ctx, width, height, st.rtl)
      return true
    },
    { reducedMotion },
  )

  // Direction, read once the element exists. History grows toward the end in both directions.
  const ref = React.useRef<HTMLDivElement>(null)
  React.useLayoutEffect(() => {
    if (ref.current) m.current.rtl = getComputedStyle(ref.current).direction === "rtl"
  })

  React.useEffect(() => {
    void [variant, active, peaks, progress, bar, gap, level]
    canvas.invalidate()
  }, [variant, active, peaks, progress, bar, gap, level, canvas.invalidate])

  const played = Math.round(clamp(progress ?? 0) * 100)
  return (
    <div
      ref={ref}
      role="img"
      aria-label={
        label ?? (isStatic ? `Waveform, ${played} percent played` : active ? "Input level" : "Idle")
      }
      data-slot="waveform"
      data-variant={variant}
      data-active={active ? "" : undefined}
      className={cn("text-(color:--chatcn-fg) relative h-8 w-full min-w-0", className)}
      {...props}
    >
      {/* Children of role="img" are presentational, so the canvas needs no aria-hidden. */}
      <canvas ref={canvas.ref} className="absolute inset-0 size-full" />
    </div>
  )
}

export default Waveform

